from pathlib import Path
import zlib,base64

def find_function_block(text, signature):
    start=text.find(signature)
    if start<0: raise RuntimeError('Not found: '+signature)
    brace=text.find('{',start); i=brace; depth=0; state='code'; quote=None
    while i<len(text):
        c=text[i]; n=text[i+1] if i+1<len(text) else ''
        if state=='code':
            if c in "'\"`": state='string'; quote=c
            elif c=='/' and n=='/': state='line'; i+=1
            elif c=='/' and n=='*': state='block'; i+=1
            elif c=='{': depth+=1
            elif c=='}':
                depth-=1
                if depth==0: return start,i+1
        elif state=='string':
            if c=='\\': i+=1
            elif c==quote: state='code'; quote=None
        elif state=='line':
            if c=='\n': state='code'
        elif state=='block':
            if c=='*' and n=='/': state='code'; i+=1
        i+=1
    raise RuntimeError('Unbalanced')

p=Path('index.html'); s=p.read_text(encoding='utf-8')
a,b=find_function_block(s,'async function renderBloccoCompleto(')
payload=zlib.decompress(base64.b64decode('')).decode('utf-8')
s=s[:a]+payload+s[b:]
s=s.replace("let draftPasto = {}; // pasto -> {fascia, modo, ricettaId, primoId, secondoId, contornoId, portataAttiva}", "/* Draft temporaneo del pasto in editing (non ancora confermato). Chiave: giorno_pasto. */\nlet draftPasto = {};",1)
s=s.replace('motor-v9-1.js?v=9','motor-v9-1.js?v=11').replace('motor-v9-2.js?v=9','motor-v9-2.js?v=11').replace('motor-v9-3.js?v=9','motor-v9-3.js?v=11').replace('motor-v9-4.js?v=9','motor-v9-4.js?v=11')
p.write_text(s,encoding='utf-8')

p=Path('motor-v9-2.js'); s=p.read_text(encoding='utf-8')
s=s.replace("// Friselle: percorso 0-2/settimana.\n    pool=pool.filter(k=>k!=='friselle'||(stato.carboidratiUsati[k]||0)<2);", "// Rispetta il tetto reale definito in CARBOIDRATI_PASTO (friselle = 1/settimana).\n    pool=pool.filter(k=>{ const c=CARBOIDRATI_PASTO[k]; return !c.limitato || (stato.carboidratiUsati[k]||0)<(c.tettoSettimanale||2); });")
s=s.replace("const cap=(k==='friselle'?2:(c.tettoSettimanale||2));","const cap=(c.tettoSettimanale||2);")
p.write_text(s,encoding='utf-8')

